{
  "technical_and_design_decisions": [
    "Relocate the gpfdist sink module from the spring-xd-modules repository into the spring-xd core codebase as a standard sink module, preserving its Project Reactor-based implementation.",
    "Introduce a pluggable ModuleRegistry abstraction; provide two distributed implementations: a Git/GitHub-backed registry for centralized version-controlled module storage and an HDFS-backed registry as default for distributed/YARN deployments.",
    "Enhance the Mail source module to accept a reference to a java-mail-properties bean and propagate those properties to the underlying Spring Integration mail adapter.",
    "Improve Flo parser endpoints in the Spring XD admin REST API to return structured, consistent JSON error responses and streamline validation.",
    "Add auto-configuration to xd-shell by checking for a default init script location or environment variables at startup and executing configuration commands automatically.",
    "Implement graceful stream undeployment by adding a drain option: stop accepting new messages but allow in-flight messages to complete before the stream is fully stopped, using Spring Integration channel shutdown hooks and container lifecycle callbacks.",
    "For RabbitMQ benchmarking, create a reusable benchmark harness that can spin up XD containers and measure scaling, rather than manual ad-hoc testing.",
    "Remove the custom-modules.zip artifact from the YARN distribution and rely on the HDFS module registry for custom module bits."
  ],
  "assumptions": [
    "The existing Spring XD codebase (Java 8, Maven, Git) is the baseline; we are extending it without major architectural refactoring.",
    "GitHub and HDFS infrastructure with appropriate credentials are available in target environments for registry backends.",
    "The Mail source module already exists; only attribute wiring and tests are needed.",
    "Flo parser endpoints are server-side components in the Spring XD admin application; client-side Flo changes are out of scope beyond error consumption.",
    "Benchmarking effort covers development of the harness and a single short validation run/analysis; extensive long-running performance tuning is out of scope.",
    "All testing is automated (unit/integration) and executed locally or in a CI-like environment; manual QA on production clusters is not included.",
    "Documentation updates are limited to README/reference docs within the repository.",
    "The developer performs all tasks alone; no separate teams are involved."
  ],
  "activities": [
    {
      "activity_id": "ACT-01",
      "activity_name": "Detailed design and technical spikes",
      "activity_description": "Analyze all user stories and produce detailed design for registry abstraction, graceful shutdown, shell auto-config, mail properties, gpfdist relocation, Flo error reporting, and benchmark harness.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "ACT-02",
      "activity_name": "Relocate gpfdist sink to core",
      "activity_description": "Copy and restructure the Project Reactor based gpfdist sink from spring-xd-modules into the core repository as a Maven module, including dependencies.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-03",
      "activity_name": "Integrate and test gpfdist sink",
      "activity_description": "Wire gpfdist sink into core build, verify it can write to GPDB/HAWQ, and add unit/integration tests.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-04",
      "activity_name": "Document gpfdist sink",
      "activity_description": "Add reference documentation and examples for the natively supported gpfdist sink.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-05",
      "activity_name": "Implement GitHub-backed ModuleRegistry",
      "activity_description": "Develop a Git/GitHub-based implementation of the ModuleRegistry interface that clones, reads, and pushes modules to a centralized GitHub repository.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "ACT-06",
      "activity_name": "Configure GitHub registry sync on upload",
      "activity_description": "Wire module upload via shell and REST API to push new/updated modules to the centralized GitHub repo and configure containers to point to it.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "ACT-07",
      "activity_name": "Integration tests for GitHub registry",
      "activity_description": "Test multi-container synchronization: module uploaded by one admin is visible to all containers via the GitHub registry.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "ACT-08",
      "activity_name": "Document GitHub registry",
      "activity_description": "Document configuration of centralized GitHub module registry.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "ACT-09",
      "activity_name": "Implement HDFS default ModuleRegistry",
      "activity_description": "Configure or implement HDFS-backed ModuleRegistry and set it as the default distributed remote location for custom modules.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "ACT-10",
      "activity_name": "Update shell/REST for HDFS upload",
      "activity_description": "Modify xd-shell and REST API to upload custom module bits directly to HDFS registry.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-11",
      "activity_name": "Remove custom-modules.zip from YARN",
      "activity_description": "Update YARN distribution build to exclude the custom-modules.zip artifact.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "ACT-12",
      "activity_name": "Tests and docs for HDFS registry",
      "activity_description": "Add tests for HDFS registry default behavior and document the change.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "ACT-13",
      "activity_name": "Enhance Mail source for java-mail-properties",
      "activity_description": "Add support for a java-mail-properties attribute referencing a util:properties bean in the Mail source and pass properties to the Spring Integration mail adapter for SSL/TLS.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-14",
      "activity_name": "Test secured Mail source",
      "activity_description": "Add integration tests using a test mail server with TLS/SSL and the java-mail-properties configuration.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "ACT-15",
      "activity_name": "Document secured Mail source",
      "activity_description": "Provide example configuration for secured IMAP/SMTP in docs.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-16",
      "activity_name": "Improve Flo parser error reporting",
      "activity_description": "Refactor existing Flo parser endpoints to provide consistent, structured JSON error responses and streamlined validation.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "ACT-17",
      "activity_name": "Test Flo parser endpoints",
      "activity_description": "Add unit tests covering parser error cases and improved error payloads.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "ACT-18",
      "activity_name": "Document Flo parser improvements",
      "activity_description": "Update Flo/parser endpoint documentation.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-19",
      "activity_name": "Shell auto-config init script",
      "activity_description": "Implement automatic execution of an init script (e.g., /etc/springxd/conf/xd-shell.init) on xd-shell startup if present.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-20",
      "activity_name": "Shell environment variable config",
      "activity_description": "Add support for environment variables to auto-configure admin server and Hadoop filesystem in xd-shell.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "ACT-21",
      "activity_name": "Test shell auto-config",
      "activity_description": "Add tests verifying init script and environment-based auto-configuration.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "ACT-22",
      "activity_name": "Document shell auto-config",
      "activity_description": "Document the auto-configuration/init file feature.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "ACT-23",
      "activity_name": "Implement graceful stream undeploy",
      "activity_description": "Add a graceful shutdown/drain option to stream undeployment so in-flight messages complete before the stream stops; implement via container lifecycle and channel shutdown.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "ACT-24",
      "activity_name": "Configure graceful shutdown timeout",
      "activity_description": "Add configuration property for drain timeout and expose option in shell/REST undeploy commands.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "ACT-25",
      "activity_name": "Test graceful shutdown",
      "activity_description": "Integration tests that undeploy a stream mid-processing and verify messages reach the sink.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "ACT-26",
      "activity_name": "Document graceful shutdown",
      "activity_description": "Document the graceful undeploy option and its use cases.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "ACT-27",
      "activity_name": "Develop Rabbit benchmark harness",
      "activity_description": "Create scripts/tooling to deploy XD containers and benchmark RabbitMQ scaling as nodes are added.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "ACT-28",
      "activity_name": "Run and analyze benchmark",
      "activity_description": "Execute the benchmark harness for a basic validation run and summarize scaling results (development/analysis effort).",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-29",
      "activity_name": "Final system integration testing",
      "activity_description": "Integrate all features and run end-to-end tests in a representative environment.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "ACT-30",
      "activity_name": "CI and packaging updates",
      "activity_description": "Update CI pipelines, Maven builds, and YARN distribution packaging to include changes and verify artifacts.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-31",
      "activity_name": "Code review and cleanup",
      "activity_description": "Self-review all code, fix minor issues, and finalize documentation.",
      "most_likely_effort": 8
    }
  ],
  "reported_total": {
    "most_likely_effort": 278
  }
}

